export type StoryTagCategory =
  | 'Genre'
  | 'Tone'
  | 'System & Progression'
  | 'Fate Threats'
  | 'Society & Economy'
  | 'Politics & War'
  | 'Romance & Affection'
  | 'Destiny & Karma'
  | 'Adventure'
  | 'Modern'
  | 'Academy & Training'
  | 'Mystery & Lore';

export type StoryTagStyle = 'all' | 'chinese' | 'korean' | 'japanese';

export type StoryTagCategoryColor =
  | 'white'
  | 'lime'
  | 'gray'
  | 'red'
  | 'green'
  | 'purple'
  | 'pink'
  | 'gold'
  | 'blue'
  | 'teal'
  | 'orange'
  | 'black';

export interface StoryTagMetadata {
  label: string;
  category: StoryTagCategory;
  styles: StoryTagStyle[];
  aliases: string[];
  color: StoryTagCategoryColor;
}

